ALTER TABLE agent_profiles ADD COLUMN tool_policy jsonb;
ALTER TABLE agent_tasks ADD COLUMN tool_grant jsonb;
CREATE TABLE agent_tool_allocations(task_id uuid PRIMARY KEY REFERENCES agent_tasks(id),request jsonb NOT NULL,request_hash text NOT NULL,state text NOT NULL,receipt jsonb,stopped boolean NOT NULL DEFAULT false,read_bytes integer NOT NULL DEFAULT 0 CHECK(read_bytes>=0),write_bytes integer NOT NULL DEFAULT 0 CHECK(write_bytes>=0),output_bytes integer NOT NULL DEFAULT 0 CHECK(output_bytes>=0),created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL);
CREATE TABLE agent_tool_calls(id uuid PRIMARY KEY,task_id uuid NOT NULL REFERENCES agent_tasks(id),model_call_id text NOT NULL,sequence integer NOT NULL,name text NOT NULL,arguments jsonb NOT NULL,input_hash text NOT NULL,state text NOT NULL,run_id uuid NOT NULL REFERENCES execution_runs(id),grant_id uuid NOT NULL REFERENCES task_grants(id),epoch integer NOT NULL,fence integer NOT NULL,observation jsonb,result_hash text,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,CONSTRAINT agent_tool_model_call UNIQUE(task_id,model_call_id),CONSTRAINT agent_tool_sequence UNIQUE(task_id,sequence));
